}

// «Москва, Сербия, Грузия, Армения» → «Москва, Сербия +2»
function areas(s) {
  const list = String(s ?? '').split(', ').filter(Boolean);
  return list.length > 2 ? `${list.slice(0, 2).join(', ')} +${list.length - 2}` : list.join(', ');
}

